CREATE TABLE IF NOT EXISTS provider_inbox_failure(provider varchar(32) NOT NULL,account varchar(128) NOT NULL,environment varchar(32) NOT NULL,event_id varchar(128) NOT NULL,failures int NOT NULL,reason varchar(1024) NOT NULL,payload json NOT NULL,failed_at datetime(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),PRIMARY KEY(provider,account,environment,event_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin;
